int N, M, S1, S2, T;
vector<tuple<int,int,bool>> adj[1005];

ll dijkstra(int src, ll k) {
    vector<ll> dist(N+1, LLONG_MAX);
    priority_queue<pli, vector<pli>, greater<pli>> pq;
    dist[src] = 0; pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;
        for (auto [v, w, mag] : adj[u]) {
            ll nd = d + (mag ? k : (ll)w);
            if (nd < dist[v]) { dist[v] = nd; pq.push({nd, v}); }
        }
    }
    return dist[T];
}

int main() {
    cin >> N >> M >> S1 >> S2 >> T;
    for (int i = 0; i < M; i++) {
        int u, v, w; bool mag; cin >> u >> v >> w >> mag;
        adj[u].push_back({v, w, mag});
        adj[v].push_back({u, w, mag});
    }
    ll ans = LLONG_MAX;
    ll prev1 = -1, prev2 = -1;
    for (ll k = 0; k <= 200000; k++) {
        ll d1 = dijkstra(S1, k), d2 = dijkstra(S2, k);
        if (d1 == LLONG_MAX || d2 == LLONG_MAX) { prev1=d1; prev2=d2; continue; }
        ans = min(ans, abs(d1 - d2));
        if (ans == 0) break;
        if (k > 0 && prev1 != LLONG_MAX && prev2 != LLONG_MAX) {
            ll s1 = d1 - prev1, s2 = d2 - prev2;
            if (s1 == (dijkstra(S1,k-1+1)-dijkstra(S1,k-1)) && s2 == (dijkstra(S2,k-1+1)-dijkstra(S2,k-1))) {
                // slopes stable, g(k) = (d1-d2) + (s1-s2)*(x-k)
                ll g = d1 - d2, slope = s1 - s2;
                if (slope == 0) { ans = min(ans, abs(g)); break; }
                // minimize |g + slope*(x-k)| for x >= k integer
                // zero at x = k - g/slope
                double xz = k - (double)g/slope;
                for (ll x = max(k, (ll)floor(xz)-1); x <= (ll)ceil(xz)+1; x++) {
                    if (x < k) continue;
                    ans = min(ans, abs(g + slope*(x-k)));
                }
                if (slope > 0 && g > 0) break; // increasing, already past min
                if (slope < 0 && g < 0) break;
                break;
            }
        }
        prev1 = d1; prev2 = d2;
    }
    cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL << 60);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    int S1, S2, T;
    cin >> S1 >> S2 >> T;
    --S1; --S2; --T;

    vector<vector<pair<int,ll>>> g0(N), g1(N); 
    // g0: normal edges
    // g1: magical edges (all share same variable length x)

    for (int i = 0; i < M; ++i) {
        int u, v, c;
        ll w = 0;
        cin >> u >> v >> c;
        --u; --v;
        if (c == 0) {
            cin >> w;
            g0[u].push_back({v, w});
            g0[v].push_back({u, w});
        } else {
            g1[u].push_back({v, 1});
            g1[v].push_back({u, 1});
        }
    }

    auto dijkstra_layers = [&](int src) {
        // dist[k][v] = minimum fixed-cost sum to reach v using exactly k magical edges
        vector<vector<ll>> dist(N + 1, vector<ll>(N, INF));
        using State = tuple<ll,int,int>; // cost, used_magic, node
        priority_queue<State, vector<State>, greater<State>> pq;
        dist[0][src] = 0;
        pq.push({0, 0, src});

        while (!pq.empty()) {
            auto [d, k, u] = pq.top();
            pq.pop();
            if (d != dist[k][u]) continue;

            for (auto [v, w] : g0[u]) {
                if (dist[k][v] > d + w) {
                    dist[k][v] = d + w;
                    pq.push({dist[k][v], k, v});
                }
            }
            if (k < N) {
                for (auto [v, _] : g1[u]) {
                    if (dist[k + 1][v] > d) {
                        dist[k + 1][v] = d;
                        pq.push({d, k + 1, v});
                    }
                }
            }
        }

        vector<pair<int,ll>> res;
        for (int k = 0; k <= N; ++k) {
            if (dist[k][T] < INF) res.push_back({k, dist[k][T]});
        }

        // Keep only lower envelope: for increasing k, keep strictly decreasing intercepts
        sort(res.begin(), res.end());
        vector<pair<int,ll>> hull;
        ll best = INF;
        for (auto [k, b] : res) {
            if (b < best) {
                hull.push_back({k, b});
                best = b;
            }
        }
        return hull; // lines y = k*x + b
    };

    auto A = dijkstra_layers(S1);
    auto B = dijkstra_layers(S2);

    auto value = [](const vector<pair<int,ll>>& lines, ll x) -> ll {
        ll ans = INF;
        for (auto [k, b] : lines) {
            ans = min(ans, b + (ll)k * x);
        }
        return ans;
    };

    ll answer = llabs(value(A, 0) - value(B, 0));

    vector<ll> cand = {0};

    // Candidate x values where a line from A and a line from B may cross in difference.
    for (auto [ka, ba] : A) {
        for (auto [kb, bb] : B) {
            ll dk = (ll)ka - kb;
            ll db = bb - ba; // solve ka*x+ba ~= kb*x+bb => dk*x ~= db
            if (dk == 0) continue;
            long double xr = (long double)db / (long double)dk;
            ll x = floor(xr);
            for (ll t = x - 2; t <= x + 2; ++t) {
                if (t >= 0) cand.push_back(t);
            }
        }
    }

    sort(cand.begin(), cand.end());
    cand.erase(unique(cand.begin(), cand.end()), cand.end());

    for (ll x : cand) {
        ll d1 = value(A, x);
        ll d2 = value(B, x);
        answer = min(answer, llabs(d1 - d2));
    }

    cout << answer << '\n';
    return 0;
}

#include <stdio.h>
