#define MAXN 1005
#define MAXM 10005
#define INF 1000000000000000000LL

typedef long long ll;

typedef struct {
    int to, next, magic;
} Edge;

Edge edges[2*MAXM];
int head[MAXN], edge_cnt;
int N, M;

void add_edge(int u, int v, int magic) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].magic = magic;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

typedef struct {
    ll d0, d1; // distances with magic=0 and magic=1
} Dist;

Dist dist1[MAXN], dist2[MAXN];

void dijkstra(int start, Dist *dist) {
    int visited[MAXN][2] = {0}; // 0 for d0, 1 for d1 dimension
    for (int i = 1; i <= N; i++) {
        dist[i].d0 = INF;
        dist[i].d1 = INF;
    }
    dist[start].d0 = 0;
    dist[start].d1 = 0;

    // Simple O(N^2) Dijkstra for clarity (N <= 1000)
    for (int iter = 0; iter < 2*N; iter++) {
        int u = -1, dim = -1;
        ll best = INF;
        for (int i = 1; i <= N; i++) {
            if (!visited[i][0] && dist[i].d0 < best) {
                best = dist[i].d0;
                u = i; dim = 0;
            }
            if (!visited[i][1] && dist[i].d1 < best) {
                best = dist[i].d1;
                u = i; dim = 1;
            }
        }
        if (u == -1) break;
        visited[u][dim] = 1;
        ll base = (dim == 0) ? dist[u].d0 : dist[u].d1;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            int magic = edges[e].magic;
            // staying in same dim if non-magical
            if (!magic) {
                if (dim == 0 && base + 1 < dist[v].d0) {
                    dist[v].d0 = base + 1;
                }
                if (dim == 1 && base + 1 < dist[v].d1) {
                    dist[v].d1 = base + 1;
                }
            } else { // magical
                // d0: cost 0
                if (dim == 0 && base < dist[v].d0) {
                    dist[v].d0 = base;
                }
                // d1: cost 1
                if (dim == 0 && base + 1 < dist[v].d1) {
                    dist[v].d1 = base + 1;
                }
                // from d1 dimension
                if (dim == 1 && base < dist[v].d1) {
                    dist[v].d1 = base;
                }
                if (dim == 1 && base + 1 < dist[v].d0) {
                    dist[v].d0 = base + 1;
                }
            }
        }
    }
}

ll minll(ll a, ll b) { return a < b ? a : b; }
ll absll(ll x) { return x < 0 ? -x : x; }

int main() {
    int S1, S2, T;
    scanf("%d %d %d %d %d", &N, &M, &S1, &S2, &T);
    memset(head, -1, sizeof(head));
    edge_cnt = 0;
    for (int i = 0; i < M; i++) {
        int u, v, magic;
        scanf("%d %d %d", &u, &v, &magic);
        add_edge(u, v, magic);
        add_edge(v, u, magic);
    }
    dijkstra(S1, dist1);
    dijkstra(S2, dist2);

    ll ans = INF;
    for (int u = 1; u <= N; u++) {
        ll a0 = dist1[u].d0 - dist2[u].d0;
        ll a1 = dist1[u].d1 - dist2[u].d1;
        // diff(x) = a0 + a1 * x
        // try x=0
        ans = minll(ans, absll(a0));
        if (a1 != 0) {
            // best x near -a0/a1
            ll x0 = -a0 / a1;
            for (ll x = x0 - 1; x <= x0 + 1; x++) {
                if (x < 0) x = 0;
                ans = minll(ans, absll(a0 + a1 * x));
                if (x > 0 && x == 0) break; // avoid infinite if x0 huge negative
            }
        }
    }
    printf("%lld\n", ans);
    return 0;
}

