#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

typedef long long ll;

#define INF64 ((ll)4e18)

typedef struct {
    int to, next;
    ll w;
    int magic;
} Edge;

typedef struct {
    ll d;
    int v;
} HeapNode;

static int N, M, S1, S2, Tt;
static int *head;
static Edge *edges;
static int ecnt = 0;

static void add_edge(int u, int v, ll w, int magic) {
    edges[ecnt].to = v;
    edges[ecnt].w = w;
    edges[ecnt].magic = magic;
    edges[ecnt].next = head[u];
    head[u] = ecnt++;
}

typedef struct {
    HeapNode *a;
    int sz, cap;
} MinHeap;

static void heap_init(MinHeap *h, int cap) {
    h->a = (HeapNode*)malloc(sizeof(HeapNode) * (cap + 5));
    h->sz = 0;
    h->cap = cap + 5;
}

static void heap_push(MinHeap *h, ll d, int v) {
    if (h->sz + 1 >= h->cap) {
        h->cap <<= 1;
        h->a = (HeapNode*)realloc(h->a, sizeof(HeapNode) * h->cap);
    }
    int i = ++h->sz;
    while (i > 1 && h->a[i >> 1].d > d) {
        h->a[i] = h->a[i >> 1];
        i >>= 1;
    }
    h->a[i].d = d;
    h->a[i].v = v;
}

static HeapNode heap_pop(MinHeap *h) {
    HeapNode ret = h->a[1];
    HeapNode x = h->a[h->sz--];
    int i = 1, c;
    while ((i << 1) <= h->sz) {
        c = i << 1;
        if (c + 1 <= h->sz && h->a[c + 1].d < h->a[c].d) c++;
        if (h->a[c].d >= x.d) break;
        h->a[i] = h->a[c];
        i = c;
    }
    h->a[i] = x;
    return ret;
}

static int heap_empty(MinHeap *h) {
    return h->sz == 0;
}

/*
We model each path length as:
fixed_sum + k * X
where k = number of magical edges used, X is the common chosen length.

For each source, compute for every vertex and every possible k (0..N-1)
the minimum fixed_sum among paths that use exactly k magical edges.
Then distance to T from source at chosen X is:
min_k (fixed_sum[k] + k*X)

This is the lower envelope of lines. We need:
min_{X >= 0} |f1(X) - f2(X)|

Since all slopes are integers in [0, N-1], and intercepts are from shortest-path DP,
the minimum of absolute difference of two lower envelopes occurs at:
- X = 0, or
- an intersection of one line from source1 and one from source2, if >= 0.
We build all relevant lines (non-dominated on lower envelope) and check candidates.

Shortest path in expanded graph:
state = (vertex, k), edges:
 non-magic: (u,k)->(v,k) cost w
 magic:     (u,k)->(v,k+1) cost 0
*/
static ll *dist_expand(int S) {
    int K = N; /* enough: simple path uses at most N-1 edges, thus magical edges too */
    int states = N * K;
    ll *dist = (ll*)malloc(sizeof(ll) * states);
    for (int i = 0; i < states; i++) dist[i] = INF64;

    MinHeap hp;
    heap_init(&hp, states + M + 10);

    dist[(S - 1) * K + 0] = 0;
    heap_push(&hp, 0, (S - 1) * K + 0);

    while (!heap_empty(&hp)) {
        HeapNode cur = heap_pop(&hp);
        ll cd = cur.d;
        int id = cur.v;
        if (cd != dist[id]) continue;

        int u = id / K + 1;
        int k = id % K;

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            int nk = k + (edges[e].magic ? 1 : 0);
            if (nk >= K) continue;
            ll nd = cd + (edges[e].magic ? 0 : edges[e].w);
            int nid = (v - 1) * K + nk;
            if (nd < dist[nid]) {
                dist[nid] = nd;
                heap_push(&hp, nd, nid);
            }
        }
    }

    free(hp.a);
    return dist;
}

typedef struct {
    ll b; /* intercept */
    int m; /* slope */
} Line;

static int cmp_line(const void *A, const void *B) {
    const Line *a = (const Line*)A;
    const Line *b = (const Line*)B;
    if (a->m != b->m) return a->m - b->m;
    if (a->b < b->b) return -1;
    if (a->b > b->b) return 1;
    return 0;
}

static long double intersect_x(Line a, Line b) {
    /* a.b + a.m*x = b.b + b.m*x, slopes different */
    return ((long double)(a.b - b.b)) / ((long double)(b.m - a.m));
}

static Line *build_hull(ll *distT, int *out_sz) {
    int K = N;
    Line *tmp = (Line*)malloc(sizeof(Line) * K);
    int cnt = 0;
    int base = (Tt - 1) * K;
    for (int k = 0; k < K; k++) {
        if (distT[base + k] < INF64 / 2) {
            tmp[cnt].m = k;
            tmp[cnt].b = distT[base + k];
            cnt++;
        }
    }
    if (cnt == 0) {
        *out_sz = 0;
        return tmp;
    }

    qsort(tmp, cnt, sizeof(Line), cmp_line);

    /* remove same slope with larger intercept */
    Line *uniq = (Line*)malloc(sizeof(Line) * cnt);
    int ucnt = 0;
    for (int i = 0; i < cnt; ) {
        int j = i;
        ll bestb = tmp[i].b;
        int m = tmp[i].m;
        while (j < cnt && tmp[j].m == m) {
            if (tmp[j].b < bestb) bestb = tmp[j].b;
            j++;
        }
        uniq[ucnt].m = m;
        uniq[ucnt].b = bestb;
        ucnt++;
        i = j;
    }
    free(tmp);

    /* lower hull for minimum queries, slopes increasing */
    Line *hull = (Line*)malloc(sizeof(Line) * ucnt);
    int hs = 0;
    for (int i = 0; i < ucnt; i++) {
        while (hs >= 2) {
            long double x1 = intersect_x(hull[hs - 2], hull[hs - 1]);
            long double x2 = intersect_x(hull[hs - 1], uniq[i]);
            if (x2 <= x1 + 1e-18L) hs--;
            else break;
        }
        hull[hs++] = uniq[i];
    }
    free(uniq);

    /* keep only lines relevant for x >= 0 */
    while (hs >= 2) {
        long double x = intersect_x(hull[0], hull[1]);
        if (x <= 0.0L + 1e-18L) {
            hull[0] = hull[1];
            memmove(hull + 1, hull + 2, sizeof(Line) * (hs - 2));
            hs--;
        } else break;
    }

    *out_sz = hs;
    return hull;
}

static ll eval_hull(Line *h, int hs, ll x) {
    ll ans = INF64;
    for (int i = 0; i < hs; i++) {
        ll val = h[i].b + (ll)h[i].m * x;
        if (val < ans) ans = val;
    }
    return ans;
}

static ll absll(ll x) { return x < 0 ? -x : x; }

int main(void) {
    if (scanf("%d %d %d %d %d", &N, &M, &S1, &S2, &Tt) != 5) return 0;

    head = (int*)malloc(sizeof(int) * (N + 1));
    for (int i = 1; i <= N; i++) head[i] = -1;
    edges = (Edge*)malloc(sizeof(Edge) * (2 * M + 5));

    for (int i = 0; i < M; i++) {
        int u, v, c;
        ll w;
        scanf("%d %d %lld %d", &u, &v, &w, &c);
        add_edge(u, v, w, c);
        add_edge(v, u, w, c);
    }

    ll *d1 = dist_expand(S1);
    ll *d2 = dist_expand(S2);

    int h1s, h2s;
    Line *h1 = build_hull(d1, &h1s);
    Line *h2 = build_hull(d2, &h2s);

    ll ans = INF64;

    /* candidate X = 0 */
    if (h1s > 0 && h2s > 0) {
        ll f10 = eval_hull(h1, h1s, 0);
        ll f20 = eval_hull(h2, h2s, 0);
        ans = absll(f10 - f20);
    }

    /* candidate intersections between hull lines */
    for (int i = 0; i < h1s; i++) {
        for (int j = 0; j < h2s; j++) {
            if (h1[i].m == h2[j].m) {
                ans = (absll(h1[i].b - h2[j].b) < ans) ? absll(h1[i].b - h2[j].b) : ans;
                continue;
            }
            long double x = ((long double)(h2[j].b - h1[i].b)) / ((long double)(h1[i].m - h2[j].m));
            if (x < -1e-18L) continue;

            ll cand[4];
            int cc = 0;
            ll xf = (ll)x;
            for (ll dx = -2; dx <= 2; dx++) {
                ll xx = xf + dx;
                if (xx >= 0) cand[cc++] = xx;
            }

            for (int t = 0; t < cc; t++) {
                ll xx = cand[t];
                ll v1 = eval_hull(h1, h1s, xx);
                ll v2 = eval_hull(h2, h2s, xx);
                ll diff = absll(v1 - v2);
                if (diff < ans) ans = diff;
            }
        }
    }

    if (ans >= INF64 / 2) ans = -1; /* unreachable safeguard */

    printf("%lld\n", ans);

    free(head);
    free(edges);
    free(d1);
    free(d2);
    free(h1);
    free(h2);
    return 0;
}

