public class MagicianRace {
    static class Edge {
        int to, len;
        boolean magical;
        Edge(int to, int len, boolean magical) {
            this.to = to;
            this.len = len;
            this.magical = magical;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        int S1 = sc.nextInt() - 1;
        int S2 = sc.nextInt() - 1;
        int T = sc.nextInt() - 1;

        List<Edge>[] graph = new ArrayList[N];
        for (int i = 0; i < N; i++) graph[i] = new ArrayList<>();

        List<int[]> magicalEdges = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            int l = sc.nextInt();
            int c = sc.nextInt();
            boolean magical = (c == 1);
            graph[u].add(new Edge(v, l, magical));
            graph[v].add(new Edge(u, l, magical));
            if (magical) {
                magicalEdges.add(new int[]{u, v, l});
            }
        }

        long[] dist1 = dijkstra(graph, S1, N);
        long[] dist2 = dijkstra(graph, S2, N);

        long answer = Math.abs(dist1[T] - dist2[T]);

        for (int[] me : magicalEdges) {
            int u = me[0], v = me[1];
            long base1 = dist1[u];
            long base2 = dist2[v];
            long base3 = dist1[v];
            long base4 = dist2[u];

            // Try orientation: S1 -> u -> v -> T
            if (base1 < Long.MAX_VALUE && dist2[v] < Long.MAX_VALUE) {
                long d1 = base1;
                long d2 = dist2[v];
                long diff = Math.abs(d1 - d2);
                answer = Math.min(answer, diff);
            }
            // Try orientation: S1 -> v -> u -> T
            if (base3 < Long.MAX_VALUE && dist2[u] < Long.MAX_VALUE) {
                long d1 = base3;
                long d2 = dist2[u];
                long diff = Math.abs(d1 - d2);
                answer = Math.min(answer, diff);
            }
        }

        System.out.println(answer);
    }

    static long[] dijkstra(List<Edge>[] graph, int start, int N) {
        long[] dist = new long[N];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[start] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[1]));
        pq.offer(new long[]{start, 0});

        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int u = (int) cur[0];
            long d = cur[1];
            if (d != dist[u]) continue;
            for (Edge e : graph[u]) {
                if (e.magical) continue; // treat magical bridges as adjustable, ignore in fixed Dijkstra
                int v = e.to;
                long nd = d + e.len;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.offer(new long[]{v, nd});
                }
            }
        }
        return dist;
    }
}

