import java.io.*;
import java.util.*;

/*
We need minimize |dist(S1,T) - dist(S2,T)| in an undirected graph.
Some edges are fixed-weight, some are "magical" and all magical edges must be assigned
the same non-negative integer x.

For any source s, shortest path to T as function of x is:
f_s(x) = min over all s-T paths P of (fixedSum(P) + x * magicCount(P))
This is a lower envelope of lines a + b x, with integer b >= 0.

We need min_{x >= 0 integer} |f1(x) - f2(x)|.

Key observations:
- For each possible number k of magical edges used, let dp_s[k] be the minimum fixed-weight
  sum among s-T paths using exactly k magical edges. Then
  f_s(x) = min_k (dp_s[k] + kx).
- Since all weights are nonnegative and magical contribution counted separately, dp_s[k]
  can be computed by shortest path on expanded state space (node, usedMagicCount), with
  cost = sum of fixed edges only, magical edges add 0 cost but increase count by 1.
- Simple paths suffice, so k <= N-1. Thus state size O(N^2), acceptable for moderate constraints.
- After obtaining all lines for both sources, remove dominated lines to build lower convex hull
  for minimum queries over x >= 0.
- The minimum absolute difference between two piecewise-linear concave-up? Actually min of lines
  gives a concave function in slope-order. We can process intervals where each hull line is active.
  Over overlap interval [L,R], difference is linear: (a1-a2) + (b1-b2)x. Minimum absolute value over
  integer x in interval occurs at endpoints or nearest integers around root.

We don't have explicit constraints in statement, so implement reasonably optimized O((N^2 + M N) log (N^2)).
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) { in = is; }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int to;
        long w;
        int magic; // 0 or 1
        Edge(int to, long w, int magic) {
            this.to = to;
            this.w = w;
            this.magic = magic;
        }
    }

    static class State implements Comparable<State> {
        int v, k;
        long d;
        State(int v, int k, long d) {
            this.v = v;
            this.k = k;
            this.d = d;
        }
        public int compareTo(State o) {
            return Long.compare(this.d, o.d);
        }
    }

    static final long INF = Long.MAX_VALUE / 4;

    static long[] computeDP(List<Edge>[] g, int src, int t, int n) {
        int K = n - 1;
        long[][] dist = new long[n][K + 1];
        for (int i = 0; i < n; i++) Arrays.fill(dist[i], INF);
        PriorityQueue<State> pq = new PriorityQueue<>();
        dist[src][0] = 0;
        pq.add(new State(src, 0, 0));

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            if (cur.d != dist[cur.v][cur.k]) continue;
            for (Edge e : g[cur.v]) {
                int nk = cur.k + e.magic;
                if (nk > K) continue;
                long nd = cur.d + (e.magic == 1 ? 0 : e.w);
                if (nd < dist[e.to][nk]) {
                    dist[e.to][nk] = nd;
                    pq.add(new State(e.to, nk, nd));
                }
            }
        }

        long[] dp = new long[K + 1];
        System.arraycopy(dist[t], 0, dp, 0, K + 1);
        return dp;
    }

    static class Line {
        long a; // intercept
        int b;  // slope
        double start; // active from this x onward on lower hull
        Line(long a, int b) {
            this.a = a;
            this.b = b;
        }
    }

    static double intersectX(Line l1, Line l2) {
        // l1.a + l1.b x = l2.a + l2.b x
        // x = (l1.a - l2.a) / (l2.b - l1.b)
        return (double)(l1.a - l2.a) / (double)(l2.b - l1.b);
    }

    static List<Line> buildHull(long[] dp) {
        List<Line> lines = new ArrayList<>();
        for (int b = 0; b < dp.length; b++) {
            if (dp[b] >= INF) continue;
            long a = dp[b];
            if (!lines.isEmpty() && lines.get(lines.size() - 1).b == b) {
                if (a < lines.get(lines.size() - 1).a) {
                    lines.get(lines.size() - 1).a = a;
                }
            } else {
                lines.add(new Line(a, b));
            }
        }

        // Remove dominated for same/increasing slopes, lower hull for min query on x>=0
        List<Line> hull = new ArrayList<>();
        for (Line ln : lines) {
            while (!hull.isEmpty() && hull.get(hull.size() - 1).a >= ln.a) {
                // Previous line with smaller slope but not better at x>=0 ever.
                hull.remove(hull.size() - 1);
            }
            while (hull.size() >= 2) {
                Line l1 = hull.get(hull.size() - 2);
                Line l2 = hull.get(hull.size() - 1);
                double x12 = intersectX(l1, l2);
                double x23 = intersectX(l2, ln);
                if (x23 <= x12 + 1e-12) hull.remove(hull.size() - 1);
                else break;
            }
            hull.add(ln);
        }

        // active starts
        for (int i = 0; i < hull.size(); i++) {
            if (i == 0) hull.get(i).start = Double.NEGATIVE_INFINITY;
            else hull.get(i).start = intersectX(hull.get(i - 1), hull.get(i));
        }

        // Since x must be >=0, trim prefix lines not active at any x>=0
        int idx = 0;
        while (idx + 1 < hull.size() && hull.get(idx + 1).start <= 0.0 + 1e-12) idx++;
        List<Line> trimmed = new ArrayList<>();
        for (int i = idx; i < hull.size(); i++) trimmed.add(hull.get(i));
        if (!trimmed.isEmpty()) trimmed.get(0).start = 0.0;
        return trimmed;
    }

    static long eval(Line l, long x) {
        return l.a + (long) l.b * x;
    }

    static long checkCandidate(long ans, Line p, Line q, long x, long L, long R) {
        if (x < L || x > R || x < 0) return ans;
        long v = Math.abs(eval(p, x) - eval(q, x));
        return Math.min(ans, v);
    }

    static long solveHulls(List<Line> h1, List<Line> h2) {
        if (h1.isEmpty() || h2.isEmpty()) return -1;
        long ans = INF;
        int i = 0, j = 0;
        while (i < h1.size() && j < h2.size()) {
            double leftD = Math.max(h1.get(i).start, h2.get(j).start);
            double rightD = Double.POSITIVE_INFINITY;
            if (i + 1 < h1.size()) rightD = Math.min(rightD, h1.get(i + 1).start);
            if (j + 1 < h2.size()) rightD = Math.min(rightD, h2.get(j + 1).start);

            long L = Math.max(0L, (long)Math.ceil(leftD - 1e-12));
            long R;
            if (Double.isInfinite(rightD)) {
                R = Long.MAX_VALUE / 8;
            } else {
                R = (long)Math.ceil(rightD - 1e-12) - 1;
            }

            if (L <= R) {
                Line p = h1.get(i), q = h2.get(j);
                long c0 = p.a - q.a;
                long c1 = (long)p.b - q.b;

                ans = checkCandidate(ans, p, q, L, L, R);
                if (R < Long.MAX_VALUE / 16) ans = checkCandidate(ans, p, q, R, L, R);

                if (c1 != 0) {
                    double root = -(double)c0 / (double)c1;
                    long f = (long)Math.floor(root);
                    for (long x = f - 2; x <= f + 2; x++) {
                        ans = checkCandidate(ans, p, q, x, L, R);
                    }
                } else {
                    ans = Math.min(ans, Math.abs(c0));
                }
            }

            double n1 = (i + 1 < h1.size()) ? h1.get(i + 1).start : Double.POSITIVE_INFINITY;
            double n2 = (j + 1 < h2.size()) ? h2.get(j + 1).start : Double.POSITIVE_INFINITY;
            if (n1 < n2 - 1e-12) i++;
            else if (n2 < n1 - 1e-12) j++;
            else { i++; j++; }
        }
        return ans;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();
        int S1 = fs.nextInt() - 1;
        int S2 = fs.nextInt() - 1;
        int T = fs.nextInt() - 1;

        List<Edge>[] g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            long w = fs.nextLong();
            int c = fs.nextInt(); // assume 1 if magical, 0 otherwise
            g[u].add(new Edge(v, w, c));
            g[v].add(new Edge(u, w, c));
        }

        long[] dp1 = computeDP(g, S1, T, N);
        long[] dp2 = computeDP(g, S2, T, N);

        List<Line> h1 = buildHull(dp1);
        List<Line> h2 = buildHull(dp2);

        long ans = solveHulls(h1, h2);
        System.out.println(ans);
    }
}
